create table if not exists academic_programmes (
  id bigserial primary key,
  institution_id int not null references institutions on delete cascade,
  programme_title text not null,
  award text not null,
  level text not null,
  catalogue_unit text not null,
  college_name text,
  school_name text,
  source_url text not null,
  active boolean not null default true,
  verified_at date not null default current_date,
  unique (institution_id, source_url)
);

alter table academic_programmes enable row level security;
drop policy if exists "academic programmes read" on academic_programmes;
create policy "academic programmes read" on academic_programmes for select using (active or is_admin());
drop policy if exists "academic programmes admin" on academic_programmes;
create policy "academic programmes admin" on academic_programmes for all using (is_admin()) with check (is_admin());

create index if not exists academic_programmes_catalogue_idx
  on academic_programmes(institution_id, college_name, school_name, catalogue_unit, level)
  where active;

